[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Fresh Pantry — Discover Everyday Deliciousness</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Nunito:wght@400;600;700;800&family=Inter:wght@400;500;600&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

    :root {
      --green: #2D6A4F;
      --green-dark: #1B4332;
      --green-light: #40916C;
      --orange: #F4A261;
      --orange-dark: #E76F51;
      --cream: #FEFAE0;
      --cream-dark: #F5F0D0;
      --white: #FFFFFF;
      --text-dark: #2C2C2C;
      --text-muted: #6B7280;
      --shadow-sm: 0 2px 8px rgba(0,0,0,0.06);
      --shadow-md: 0 4px 16px rgba(0,0,0,0.08);
      --shadow-lg: 0 8px 32px rgba(0,0,0,0.10);
      --radius: 16px;
      --radius-sm: 12px;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: 'Inter', sans-serif;
      color: var(--text-dark);
      background: var(--cream);
      line-height: 1.6;
      overflow-x: hidden;
    }

    h1, h2, h3, h4, h5, h6 {
      font-family: 'Nunito', sans-serif;
      line-height: 1.2;
    }

    a { text-decoration: none; color: inherit; }
    img { max-width: 100%; display: block; }
    button { cursor: pointer; font-family: 'Inter', sans-serif; border: none; }
    input { font-family: 'Inter', sans-serif; }

    .container {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
    }

    /* ========== HEADER ========== */
    .header {
      position: sticky;
      top: 0;
      z-index: 100;
      background: rgba(254, 250, 224, 0.92);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      border-bottom: 1px solid rgba(45, 106, 79, 0.08);
    }

    .header .container {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 72px;
    }

    .logo {
      display: flex;
      align-items: center;
      gap: 10px;
      font-family: 'Nunito', sans-serif;
      font-weight: 800;
      font-size: 1.5rem;
      color: var(--green);
    }

    .logo-icon {
      width: 40px;
      height: 40px;
      background: var(--green);
      border-radius: 12px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.3rem;
    }

    .nav { display: flex; gap: 32px; align-items: center; }

    .nav a {
      font-weight: 500;
      font-size: 0.95rem;
      color: var(--text-dark);
      transition: color 0.2s;
      position: relative;
    }

    .nav a::after {
      content: '';
      position: absolute;
      bottom: -4px;
      left: 0;
      width: 0;
      height: 2px;
      background: var(--green);
      border-radius: 2px;
      transition: width 0.3s;
    }

    .nav a:hover { color: var(--green); }
    .nav a:hover::after { width: 100%; }

    .hamburger {
      display: none;
      flex-direction: column;
      gap: 5px;
      background: none;
      padding: 8px;
    }

    .hamburger span {
      display: block;
      width: 24px;
      height: 2.5px;
      background: var(--green);
      border-radius: 2px;
      transition: 0.3s;
    }

    /* ========== HERO ========== */
    .hero {
      padding: 80px 0 100px;
      background: linear-gradient(135deg, var(--cream) 0%, #E8F5E9 50%, var(--cream-dark) 100%);
      position: relative;
      overflow: hidden;
    }

    .hero::before {
      content: '';
      position: absolute;
      top: -60px;
      right: -120px;
      width: 500px;
      height: 500px;
      background: radial-gradient(circle, rgba(244,162,97,0.12) 0%, transparent 70%);
      border-radius: 50%;
    }

    .hero::after {
      content: '';
      position: absolute;
      bottom: -80px;
      left: -100px;
      width: 400px;
      height: 400px;
      background: radial-gradient(circle, rgba(45,106,79,0.08) 0%, transparent 70%);
      border-radius: 50%;
    }

    .hero .container {
      display: flex;
      align-items: center;
      gap: 60px;
      position: relative;
      z-index: 1;
    }

    .hero-text { flex: 1; max-width: 580px; }

    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      background: rgba(45, 106, 79, 0.1);
      color: var(--green);
      font-weight: 600;
      font-size: 0.85rem;
      padding: 6px 14px;
      border-radius: 100px;
      margin-bottom: 20px;
    }

    .hero h1 {
      font-size: 3.5rem;
      font-weight: 800;
      color: var(--green-dark);
      margin-bottom: 20px;
      letter-spacing: -0.02em;
    }

    .hero h1 span {
      color: var(--orange);
    }

    .hero p {
      font-size: 1.2rem;
      color: var(--text-muted);
      margin-bottom: 36px;
      max-width: 480px;
    }

    .hero-buttons { display: flex; gap: 16px; flex-wrap: wrap; }

    .btn-primary {
      background: var(--green);
      color: var(--white);
      padding: 16px 32px;
      border-radius: 100px;
      font-weight: 600;
      font-size: 1rem;
      transition: all 0.3s;
      display: inline-flex;
      align-items: center;
      gap: 8px;
    }

    .btn-primary:hover {
      background: var(--green-dark);
      transform: translateY(-2px);
      box-shadow: 0 8px 24px rgba(45,106,79,0.25);
    }

    .btn-secondary {
      background: var(--white);
      color: var(--green);
      padding: 16px 32px;
      border-radius: 100px;
      font-weight: 600;
      font-size: 1rem;
      border: 2px solid var(--green);
      transition: all 0.3s;
      display: inline-flex;
      align-items: center;
      gap: 8px;
    }

    .btn-secondary:hover {
      background: var(--green);
      color: var(--white);
      transform: translateY(-2px);
    }

    .hero-visual {
      flex: 1;
      display: flex;
      justify-content: center;
      align-items: center;
    }

    .hero-image-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 16px;
      max-width: 400px;
    }

    .hero-image-card {
      border-radius: var(--radius);
      overflow: hidden;
      box-shadow: var(--shadow-md);
      aspect-ratio: 1;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 3rem;
      transition: transform 0.4s;
    }

    .hero-image-card:hover { transform: scale(1.05) rotate(-1deg); }
    .hero-image-card:nth-child(1) { background: linear-gradient(135deg, #A8E6CF, #88D8B0); }
    .hero-image-card:nth-child(2) { background: linear-gradient(135deg, #FFD3B6, #FFAAA5); transform: translateY(20px); }
    .hero-image-card:nth-child(3) { background: linear-gradient(135deg, #DCEDC1, #A8E6CF); transform: translateY(-20px); }
    .hero-image-card:nth-child(4) { background: linear-gradient(135deg, #FFECD2, #FCB69F); }

    /* ========== FEATURED PRODUCTS ========== */
    .featured-products {
      padding: 100px 0;
      background: var(--white);
    }

    .section-header {
      text-align: center;
      margin-bottom: 48px;
    }

    .section-header h2 {
      font-size: 2.4rem;
      font-weight: 800;
      color: var(--green-dark);
      margin-bottom: 12px;
    }

    .section-header p {
      font-size: 1.1rem;
      color: var(--text-muted);
      max-width: 520px;
      margin: 0 auto;
    }

    .carousel-wrapper {
      position: relative;
      overflow: hidden;
    }

    .carousel-track {
      display: flex;
      gap: 24px;
      transition: transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
      padding: 8px 0;
    }

    .product-card {
      min-width: 260px;
      background: var(--cream);
      border-radius: var(--radius);
      overflow: hidden;
      box-shadow: var(--shadow-sm);
      transition: all 0.3s;
      flex-shrink: 0;
    }

    .product-card:hover {
      transform: translateY(-6px);
      box-shadow: var(--shadow-lg);
    }

    .product-card-image {
      height: 180px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 3.5rem;
      position: relative;
    }

    .product-tag {
      position: absolute;
      top: 12px;
      left: 12px;
      background: var(--orange);
      color: var(--white);
      font-size: 0.75rem;
      font-weight: 700;
      padding: 4px 10px;
      border-radius: 100px;
    }

    .product-card-body {
      padding: 20px;
    }

    .product-card-body h3 {
      font-size: 1.05rem;
      font-weight: 700;
      color: var(--text-dark);
      margin-bottom: 6px;
    }

    .product-card-body .description {
      font-size: 0.85rem;
      color: var(--text-muted);
      margin-bottom: 14px;
      line-height: 1.5;
    }

    .product-card-footer {
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .product-price {
      font-family: 'Nunito', sans-serif;
      font-size: 1.3rem;
      font-weight: 800;
      color: var(--green);
    }

    .product-add-btn {
      width: 36px;
      height: 36px;
      border-radius: 50%;
      background: var(--green);
      color: var(--white);
      font-size: 1.3rem;
      display: flex;
      align-items: center;
      justify-content: center;
      transition: all 0.2s;
      line-height: 1;
    }

    .product-add-btn:hover {
      background: var(--green-dark);
      transform: scale(1.1);
    }

    .carousel-btn {
      position: absolute;
      top: 50%;
      transform: translateY(-50%);
      width: 48px;
      height: 48px;
      border-radius: 50%;
      background: var(--white);
      box-shadow: var(--shadow-md);
      display: flex;
      align-items: center;
      justify-content: center;
      z-index: 10;
      transition: all 0.2s;
      font-size: 1.2rem;
      color: var(--green);
      border: 2px solid rgba(45,106,79,0.1);
    }

    .carousel-btn:hover {
      background: var(--green);
      color: var(--white);
      transform: translateY(-50%) scale(1.05);
    }

    .carousel-btn.prev { left: -8px; }
    .carousel-btn.next { right: -8px; }

    .carousel-btn:disabled {
      opacity: 0.3;
      cursor: not-allowed;
    }

    .carousel-btn:disabled:hover {
      background: var(--white);
      color: var(--green);
      transform: translateY(-50%);
    }

    /* ========== SEASONAL PICKS ========== */
    .seasonal-picks {
      padding: 100px 0;
      background: linear-gradient(180deg, var(--cream) 0%, #FFF9E6 100%);
    }

    .seasonal-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 24px;
    }

    .seasonal-card {
      background: var(--white);
      border-radius: var(--radius);
      padding: 28px;
      box-shadow: var(--shadow-sm);
      transition: all 0.3s;
      position: relative;
      overflow: hidden;
    }

    .seasonal-card::before {
      content: '';
      position: absolute;
      top: 0;
      left: 0;
      right: 0;
      height: 4px;
      background: linear-gradient(90deg, var(--orange), var(--orange-dark));
      border-radius: var(--radius) var(--radius) 0 0;
    }

    .seasonal-card:hover {
      transform: translateY(-6px);
      box-shadow: var(--shadow-lg);
    }

    .seasonal-emoji {
      font-size: 2.5rem;
      margin-bottom: 16px;
    }

    .seasonal-card h3 {
      font-size: 1.05rem;
      font-weight: 700;
      margin-bottom: 8px;
      color: var(--text-dark);
    }

    .seasonal-card .description {
      font-size: 0.88rem;
      color: var(--text-muted);
      margin-bottom: 16px;
      line-height: 1.5;
    }

    .seasonal-card .price {
      font-family: 'Nunito', sans-serif;
      font-size: 1.25rem;
      font-weight: 800;
      color: var(--orange-dark);
    }

    /* ========== CATEGORIES ========== */
    .categories {
      padding: 100px 0;
      background: var(--white);
    }

    .categories-grid {
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: 20px;
    }

    .category-card {
      position: relative;
      border-radius: var(--radius);
      overflow: hidden;
      aspect-ratio: 0.85;
      cursor: pointer;
      box-shadow: var(--shadow-sm);
    }

    .category-bg {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 3.5rem;
      transition: transform 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    }

    .category-card:nth-child(1) .category-bg { background: linear-gradient(135deg, #FFE0B2, #FFCC80); }
    .category-card:nth-child(2) .category-bg { background: linear-gradient(135deg, #C8E6C9, #A5D6A7); }
    .category-card:nth-child(3) .category-bg { background: linear-gradient(135deg, #B3E5FC, #81D4FA); }
    .category-card:nth-child(4) .category-bg { background: linear-gradient(135deg, #F8BBD0, #F48FB1); }
    .category-card:nth-child(5) .category-bg { background: linear-gradient(135deg, #FFF9C4, #FFF176); }

    .category-overlay {
      position: absolute;
      inset: 0;
      background: rgba(27, 67, 50, 0.75);
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      opacity: 0;
      transition: opacity 0.3s;
      padding: 20px;
      text-align: center;
    }

    .category-card:hover .category-bg { transform: scale(1.08); }
    .category-card:hover .category-overlay { opacity: 1; }

    .category-overlay h3 {
      color: var(--white);
      font-size: 1.15rem;
      font-weight: 700;
      margin-bottom: 8px;
    }

    .category-overlay p {
      color: rgba(255,255,255,0.85);
      font-size: 0.82rem;
    }

    .category-label {
      position: absolute;
      bottom: 0;
      left: 0;
      right: 0;
      padding: 14px;
      background: linear-gradient(transparent, rgba(0,0,0,0.5));
      transition: opacity 0.3s;
    }

    .category-card:hover .category-label { opacity: 0; }

    .category-label h3 {
      color: var(--white);
      font-size: 0.95rem;
      font-weight: 700;
    }

    /* ========== BRAND HIGHLIGHTS ========== */
    .highlights {
      padding: 80px 0;
      background: linear-gradient(135deg, var(--green-dark) 0%, var(--green) 50%, var(--green-light) 100%);
      color: var(--white);
      position: relative;
      overflow: hidden;
    }

    .highlights::before {
      content: '';
      position: absolute;
      top: -40%;
      right: -10%;
      width: 400px;
      height: 400px;
      background: rgba(255,255,255,0.04);
      border-radius: 50%;
    }

    .highlights-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 40px;
      text-align: center;
      position: relative;
      z-index: 1;
    }

    .highlight-item { padding: 20px; }

    .highlight-number {
      font-family: 'Nunito', sans-serif;
      font-size: 3rem;
      font-weight: 800;
      margin-bottom: 8px;
      color: var(--orange);
    }

    .highlight-label {
      font-size: 1.1rem;
      font-weight: 600;
      margin-bottom: 6px;
    }

    .highlight-desc {
      font-size: 0.88rem;
      opacity: 0.75;
      line-height: 1.5;
    }

    /* ========== STORE LOCATOR ========== */
    .store-locator {
      padding: 100px 0;
      background: var(--cream);
    }

    .store-search-box {
      max-width: 560px;
      margin: 0 auto 40px;
      display: flex;
      gap: 12px;
    }

    .store-search-box input {
      flex: 1;
      padding: 16px 24px;
      border: 2px solid rgba(45,106,79,0.15);
      border-radius: 100px;
      font-size: 1rem;
      background: var(--white);
      outline: none;
      transition: border-color 0.2s;
    }

    .store-search-box input:focus { border-color: var(--green); }

    .store-search-box button {
      padding: 16px 32px;
      background: var(--green);
      color: var(--white);
      border-radius: 100px;
      font-weight: 600;
      font-size: 1rem;
      transition: all 0.3s;
    }

    .store-search-box button:hover {
      background: var(--green-dark);
      transform: translateY(-2px);
      box-shadow: 0 6px 20px rgba(45,106,79,0.25);
    }

    .store-results {
      display: none;
      max-width: 800px;
      margin: 0 auto;
    }

    .store-results.active { display: block; }

    .store-results-header {
      font-family: 'Nunito', sans-serif;
      font-size: 1.1rem;
      font-weight: 700;
      color: var(--green);
      margin-bottom: 20px;
      text-align: center;
    }

    .store-card {
      background: var(--white);
      border-radius: var(--radius);
      padding: 24px 28px;
      margin-bottom: 16px;
      box-shadow: var(--shadow-sm);
      display: flex;
      align-items: center;
      justify-content: space-between;
      transition: all 0.3s;
    }

    .store-card:hover {
      box-shadow: var(--shadow-md);
      transform: translateX(4px);
    }

    .store-info { flex: 1; }

    .store-info h3 {
      font-size: 1.1rem;
      font-weight: 700;
      color: var(--text-dark);
      margin-bottom: 4px;
    }

    .store-info .address {
      font-size: 0.9rem;
      color: var(--text-muted);
      margin-bottom: 2px;
    }

    .store-info .hours {
      font-size: 0.85rem;
      color: var(--green);
      font-weight: 500;
    }

    .store-distance {
      font-family: 'Nunito', sans-serif;
      font-size: 1.3rem;
      font-weight: 800;
      color: var(--orange-dark);
      white-space: nowrap;
      margin-left: 24px;
    }

    /* ========== NEWSLETTER ========== */
    .newsletter {
      padding: 80px 0;
      background: linear-gradient(135deg, var(--orange) 0%, var(--orange-dark) 100%);
      color: var(--white);
      text-align: center;
      position: relative;
      overflow: hidden;
    }

    .newsletter::before {
      content: '';
      position: absolute;
      top: -60%;
      left: -10%;
      width: 500px;
      height: 500px;
      background: rgba(255,255,255,0.06);
      border-radius: 50%;
    }

    .newsletter h2 {
      font-size: 2.4rem;
      font-weight: 800;
      margin-bottom: 12px;
      position: relative;
      z-index: 1;
    }

    .newsletter > .container > p {
      font-size: 1.1rem;
      opacity: 0.9;
      margin-bottom: 36px;
      max-width: 520px;
      margin-left: auto;
      margin-right: auto;
      position: relative;
      z-index: 1;
    }

    .newsletter-form {
      max-width: 480px;
      margin: 0 auto;
      display: flex;
      gap: 12px;
      position: relative;
      z-index: 1;
    }

    .newsletter-form input {
      flex: 1;
      padding: 16px 24px;
      border: none;
      border-radius: 100px;
      font-size: 1rem;
      outline: none;
    }

    .newsletter-form button {
      padding: 16px 28px;
      background: var(--green-dark);
      color: var(--white);
      border-radius: 100px;
      font-weight: 600;
      font-size: 1rem;
      transition: all 0.3s;
    }

    .newsletter-form button:hover {
      background: var(--green);
      transform: translateY(-2px);
    }

    .newsletter-success {
      display: none;
      font-size: 1.05rem;
      font-weight: 600;
      margin-top: 20px;
      padding: 14px 28px;
      background: rgba(255,255,255,0.2);
      border-radius: 100px;
      max-width: 480px;
      margin-left: auto;
      margin-right: auto;
      position: relative;
      z-index: 1;
    }

    .newsletter-success.active { display: block; }

    /* ========== FOOTER ========== */
    .footer {
      padding: 60px 0 30px;
      background: var(--green-dark);
      color: var(--white);
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 40px;
      margin-bottom: 48px;
    }

    .footer-col h4 {
      font-family: 'Nunito', sans-serif;
      font-size: 1rem;
      font-weight: 700;
      margin-bottom: 20px;
      color: var(--orange);
    }

    .footer-col a {
      display: block;
      font-size: 0.9rem;
      color: rgba(255,255,255,0.7);
      margin-bottom: 12px;
      transition: color 0.2s;
    }

    .footer-col a:hover { color: var(--white); }

    .footer-bottom {
      border-top: 1px solid rgba(255,255,255,0.1);
      padding-top: 24px;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .footer-bottom p {
      font-size: 0.85rem;
      opacity: 0.6;
    }

    .footer-logo {
      font-family: 'Nunito', sans-serif;
      font-weight: 800;
      font-size: 1.2rem;
      display: flex;
      align-items: center;
      gap: 8px;
    }

    /* ========== RESPONSIVE ========== */
    @media (max-width: 1024px) {
      .hero h1 { font-size: 2.8rem; }
      .categories-grid { grid-template-columns: repeat(3, 1fr); }
      .highlights-grid { grid-template-columns: repeat(2, 1fr); }
      .seasonal-grid { grid-template-columns: repeat(2, 1fr); }
    }

    @media (max-width: 768px) {
      .nav { display: none; }
      .hamburger { display: flex; }

      .nav.open {
        display: flex;
        flex-direction: column;
        position: absolute;
        top: 72px;
        left: 0;
